const ts = require("./node_modules/typescript"); const path = require("node:path");
const configPath = path.resolve("tsconfig.json");
const raw = ts.readConfigFile(configPath, ts.sys.readFile); if(raw.error) throw Error(ts.flattenDiagnosticMessageText(raw.error.messageText,"\n"));
const parsed = ts.parseJsonConfigFileContent(raw.config, ts.sys, path.dirname(configPath));
const files = ["lib/tradeValue/valuationComponents.ts", "lib/tradeValue/valuationComponents.test.ts", "next-bootstrap.d.ts", "yahoo-fantasy.d.ts"].map(file=>path.resolve(file));
const program = ts.createProgram(files, parsed.options);
const diagnostics = [...parsed.errors,...ts.getPreEmitDiagnostics(program)];
if(diagnostics.length) console.log(ts.formatDiagnosticsWithColorAndContext(diagnostics,{getCurrentDirectory:ts.sys.getCurrentDirectory,getCanonicalFileName:f=>f,getNewLine:()=>"\n"}));
console.log(JSON.stringify({config:configPath,target:ts.ScriptTarget[parsed.options.target],roots:files,diagnostics:diagnostics.length}));process.exitCode=diagnostics.length?1:0;
